public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    if (nums == null || nums.length == 0) {
        return result;
    }
    List<Integer> list = new ArrayList<>();
    for (int i = 0; i < nums.length; i++) {
        list.add(nums[i]);
    }
    result.add(list);
    int k = 0;
    while (k < nums.length) {
        if (list.get(k) != nums[k]) {
            break;
        }
        k++;
    }
    if (k == nums.length) {
        return result;
    }
    List<List<Integer>> newResult = new ArrayList<>();
    for (List<Integer> l : result) {
        for (int i = 0; i < l.size(); i++) {
            if (l.get(i) == nums[k]) {
                List<Integer> newList = new ArrayList<>(l);
                newList.remove(i);
                newList.add(k, nums[k]);
                newResult.add(newList);
            }
        }
    }
    return newResult;
}

public List<List<Integer>> permute(int[] nums) {   
   List<List<Integer>> result = new ArrayList<>();   
   if (nums == null || nums.length == 0) {  
      return result;  
   }   
   int n = nums.length;  
   int[] indexes = new int[n];  
   for (int i = 0; i < n; i++) {  
      indexes[i] = i;  
   }      
   while (true) {  
      List<Integer> currPerm = new ArrayList<>();  
      for (int i = 0; i < n; i++) {  
         currPerm.add(nums[indexes[i]]);  
      }      
      result.add(currPerm);  
      int k = -1;  
      for (int i = 0; i < n - 1; i++) {  
         if (indexes[i] < indexes[i + 1]) {  
            k = i;  
         }  
      }      
      if (k == -1) {  
         break;  
      }  
      int l = indexes.length - 1;  
      for (int i = k + 1; i < n; i++) {  
         if (indexes[i] < indexes[k]) {  
            l = i;  
         }  
      }  
      swap(indexes, k, l);  
      reverse(indexes, k + 1, n - 1);  
   }  
   return result;  
}

