int findLargestSubstring(List<String> strings) {
    int maxLength = 0;
    for (String s : strings) {
        maxLength = Math.max(maxLength, s.length());
    }
    for (int length = maxLength; length > 0; length--) {
        for (String s : strings) {
            if (s.length() < length) {
                continue;
            }
            int start = 0;
            int end = length;
            while (end <= s.length()) {
                if (strings.contains(s.substring(start, end))) {
                    return length;
                }
                start++;
                end++;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    // Convert the list of strings to an array of StringSets
    StringSets[] stringSets = new StringSets[strings.size()];
    for (int i = 0; i < strings.size(); i++) {
        stringSets[i] = new StringSets(strings.get(i));
    }

    // Define a recursive function to find the largest substring
    int largestSubstringSize = 0;
    List<StringSets> largestSubstring = null;
    void findSubstring(List<StringSets> substring, int index) {
        if (substring.size() > largestSubstringSize) {
            largestSubstringSize = substring.size();
            largestSubstring = substring;
        }
        for (int i = 0; i < stringSets.length; i++) {
            if (substring.contains(stringSets[i])) {
                List<StringSets> newSubstring = new ArrayList<>(substring);
                newSubstring.add(stringSets[i]);
                findSubstring(newSubstring, index + 1);
            }
        }
    }

    // Find the largest substring starting from each string
    for (int i = 0; i < stringSets.length; i++) {
        List<StringSets> substring = new ArrayList<>();
        substring.add(stringSets[i]);
        findSubstring(substring, i + 1);
    }

    // Return the size of the largest substring
    return largestSubstringSize;
}

