public static String convertDatesToWeekdays(String date) {
    // Split the input date into an array of strings using the " " delimiter
    String[] dateParts = date.split(" ");

    // Parse the month, day, and year from the date parts
    int month = Integer.parseInt(dateParts[0]);
    int day = Integer.parseInt(dateParts[1]);
    int year = Integer.parseInt(dateParts[2]);

    // Create a LocalDate object from the parsed date parts
    LocalDate localDate = LocalDate.of(year, month, day);

    // Use the DayOfWeek enum to get the weekday of the LocalDate object
    DayOfWeek weekday = localDate.getDayOfWeek();

    // Return the name of the weekday and the original input date
    return weekday.toString() + ", " + date;
}

public static String convertDatesToWeekdays(String date) {
        SimpleDateFormat format = new SimpleDateFormat("MMdd yyyy");
        Date inputDate = format.parse(date);
        Calendar calendar = Calendar.getInstance();
        calendar.setTime(inputDate);
        String weekday = null;
        switch (calendar.get(Calendar.DAY_OF_WEEK)) {
            case Calendar.SUNDAY:
                weekday = "Sunday"
                break;
            case Calendar.MONDAY:
                weekday = "Monday"
                break;
            case Calendar.TUESDAY:
                weekday = "Tuesday"
                break;
            case Calendar.WEDNESDAY:
                weekday = "Wednesday"
                break;
            case Calendar.THURSDAY:
                weekday = "Thursday"
                break;
            case Calendar.FRIDAY:
                weekday = "Friday"
                break;
            case Calendar.SATURDAY:
                weekday = "Saturday"
                break;
        }
        return inputDate.toString() + " is a " + weekday;
    }

