    // Initialize the distance from node 0 to all other nodes
    int[] distance = new int[n];
    for (int i = 0; i < n; i++) {
        distance[i] = i == 0 ? 0 : Integer.MAX_VALUE;
    }

    // Initialize the parent of each node
    int[] parent = new int[n];
    for (int i = 0; i < n; i++) {
        parent[i] = -1;
    }

    // Perform Breadth-First Search from node 0
    Queue<Integer> queue = new LinkedList<>();
    queue.add(0);
    while (!queue.isEmpty()) {
        int curr = queue.poll();
        for (int neighbor : graph.getNeighbors(curr)) {
            if (hasApple[neighbor] && distance[curr] + 1 < distance[neighbor]) {
                distance[neighbor] = distance[curr] + 1;
                parent[neighbor] = curr;
                queue.add(neighbor);
            }
        }
    }

    // Calculate the minimum time required to collect all apples and return to node 0
    int minTime = Integer.MAX_VALUE;
    for (int i = 0; i < n; i++) {
        if (hasApple[i]) {
            minTime = Math.min(minTime, distance[i] + 1);
        }
    }

    return minTime;
}

