public String sortString(String s) {
    int n = s.length();
    String sorted = "";

    // step 1: find the smallest character
    int smallest = -1;
    for (int i = 0; i < n; i++) {
        if (smallest == -1 || s.charAt(i) < s.charAt(smallest)) {
            smallest = i;
        }
    }

    // step 2: find the second smallest character
    int secondSmallest = -1;
    for (int i = 0; i < n; i++) {
        if (i != smallest && (secondSmallest == -1 || s.charAt(i) < s.charAt(secondSmallest))) {
            secondSmallest = i;
        }
    }

    // step 3: append the smallest and second smallest characters to the sorted string
    sorted += s.charAt(smallest) + s.charAt(secondSmallest);

    // step 4: find the largest character
    int largest = -1;
    for (int i = 0; i < n; i++) {
        if (largest == -1 || s.charAt(i) > s.charAt(largest)) {
            largest = i;
        }
    }

    // step 5: find the second largest character
    int secondLargest = -1;
    for (int i = 0; i < n; i++) {
        if (i != largest && (secondLargest == -1 || s.charAt(i) > s.charAt(secondLargest))) {
            secondLargest = i;
        }
    }

    // step 6: append the largest and second largest characters to the sorted string
    sorted += s.charAt(largest) + s.charAt(secondLargest);

    // step 7: repeat steps 1-6 until all characters are used
    while (sorted.length() < n) {
        sorted += s.charAt(smallest) + s.charAt(secondSmallest);
        smallest = -1;
        secondSmallest = -1;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) > s.charAt(largest)) {
                largest = i;
            }
        }
        if (largest != -1) {
            sorted += s.charAt(largest);
            largest = -1;
        }
    }

    return sorted;
}

