public int minCostClimbingStairs(int[] cost) {
    int minCost = Integer.MAX_VALUE;
    int currentCost = 0;
    for (int i = 0; i < cost.length; i++) {
        currentCost += cost[i];
        if (i == cost.length - 1) {
            minCost = Math.min(minCost, currentCost);
            break;
        } else if (i + 1 < cost.length && cost[i] > cost[i + 1]) {
            continue;
        } else {
            minCost = Math.min(minCost, currentCost);
            currentCost -= cost[i];
        }
    }
    return minCost;
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int[] dp = new int[n];
    dp[0] = cost[0];
    dp[1] = cost[1];
    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 1], dp[i - 2]) + cost[i];
    }
    return Math.min(dp[n - 1], dp[n - 2]);
}

