public int minCostClimbingStairs(int[] cost) {
    if (cost.length == 0) {
        return 0;
    }
    int prevTwo = cost[0];
    int prevOne = cost[0];
    for (int i = 0; i < cost.length; i++) {
        int intIt = cost[i];
        prevTwo = prevTwo + intIt;
        prevOne = min(prevTwo, prevOne + intIt);
    }
    return prevOne;
}

public int minCostClimbingStairs(int[] cost) {
  int minCost = Integer.MAX_VALUE;
  for (int i = 0; i < cost.length; i++) {
    if (cost[i] < minCost) {
      minCost = cost[i];
    }
  }
  return minCost;
}

