}

public boolean hasAllCodes(String s, int k) {
    if (k > s.length()) {
        return false;
    }
    for (int i = 0; i <= s.length() - k; i++) {
        String substr = s.substring(i, i + k);
        for (int j = 0; j < (1 << k); j++) {
            String binary = Integer.toBinaryString(j);
            if (binary.length() < k) {
                binary = "0" + binary;
            }
            if (!substr.contains(binary)) {
                return false;
            }
        }
    }
    return true;
}

