public int minInsertions(String s) {
    int leftBrackets = 0;
    int rightBrackets = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            leftBrackets++;
        } else if (c == ')') {
            rightBrackets++;
        }
    }
    int difference = Math.abs(leftBrackets - rightBrackets);
    return difference / 2 + difference % 2;
}

public int minInsertions(String s) {
    int leftCount = 0;
    int rightCount = 0;
    int leftInsertions = 0;
    int rightInsertions = 0;

    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '(') {
            leftCount++;
        } else if (s.charAt(i) == ')') {
            rightCount++;
        }
        if (rightCount > leftCount) {
            leftInsertions++;
        } else if (rightCount < leftCount) {
            rightInsertions++;
        }
    }

    return leftInsertions + rightInsertions;
}

public int minInsertions(String s) {
    int left = 0;
    int right = 0;
    int n = s.length();
    for (int i = 0; i < n; i++) {
        if (s.charAt(i) == '(') left++;
        else right++;
        if (left == right) return n - 2 * left;
        if (right > left) return n - 2 * right;
    }
    return n - 2 * left;
}

