public int findMinFibonacciNumbers(int k) {
    int fib1 = 1;
    int fib2 = 1;
    int fib3 = 2;
    int fib4 = 3;
    int count = 0;
    while (fib3 < k) {
        int sum = fib3 + fib4;
        if (sum == k) {
            count += 2;
            return count;
        } else if (sum < k) {
            fib1 = fib2;
            fib2 = fib3;
            fib3 = sum;
            count++;
        } else {
            fib3 = fib4;
            fib4 = sum;
        }
    }
    return count;
}

