    while (fib1 + fib2 < k) {
        // Calculate the next Fibonacci number
        int fibN = fib1 + fib2;

        // Add the current Fibonacci number to the list
        fibList.add(fibN);

        // Update the variables storing the last two Fibonacci numbers
        fib1 = fib2;
        fib2 = fibN;
    }

    // Initialize a variable to store the minimum number of Fibonacci numbers
    int minFibNum = 0;

    // Loop through the list of Fibonacci numbers in reverse order
    for (int i = fibList.size() - 1; i >= 0; i--) {
        // Check if the current Fibonacci number is less than or equal to k
        if (fibList.get(i) <= k) {
            // Increment the minimum number of Fibonacci numbers
            minFibNum++;

            // Decrease k by the current Fibonacci number
            k -= fibList.get(i);
        }
    }

    return minFibNum;
}

