public static String makeGood(String s) {
    // Initialize an empty string builder to store the final good string
    StringBuilder goodString = new StringBuilder();

    // Loop through each character in the input string
    for (int i = 0; i < s.length(); i++) {
        // Get the current character and its lowercase equivalent
        char currentChar = s.charAt(i);
        char lowercaseChar = Character.toLowerCase(currentChar);

        // If the current character is a lowercase letter and the next character is its uppercase equivalent,
        // or if the current character is an uppercase letter and the previous character is its lowercase equivalent,
        // then remove both characters from the good string.
        // Otherwise, add the current character to the good string.
        if ((currentChar == lowercaseChar && i + 1 < s.length() && s.charAt(i + 1) == lowercaseChar) ||
             (currentChar == Character.toUpperCase(currentChar) && i - 1 >= 0 && s.charAt(i - 1) == lowercaseChar)) {
            continue;
        } else {
            goodString.append(currentChar);
        }
    }

    // Return the final good string
    return goodString.toString();
}

