    }
    sb.append(s.charAt(s.length() - 1));
    return sb.toString();
}

public int maxUniqueSplit(String s) {
    int n = s.length();
    int[] dp = new int[n];
    dp[0] = 1;
    for (int i = 1; i < n; i++) {
        dp[i] = dp[i - 1];
        for (int j = 0; j < i; j++) {
            if (s.substring(j, i + 1).equals(s.substring(i - j, i + 1)) && dp[j] + 1 > dp[i]) {
                dp[i] = dp[j] + 1;
            }
        }
    }
    return dp[n - 1];
}

public int maxUniqueSplit(String s) {
    int max = 0;
    int left = 0;
    int right = 0;
    Set<String> set = new HashSet<>();
    while (right < s.length()) {
        String substr = s.substring(left, right + 1);
        if (set.add(substr)) {
            max = Math.max(max, right - left + 1);
        } else {
            set.remove(s.substring(left, left + 1));
            left++;
        }
        right++;
    }
    return max;
}

public int maxUniqueSplit(String s) {
    // Initialize a set to store unique substrings
    Set<String> sets = new HashSet<>();
    // Initialize the maximum number of unique substrings
    int max = 0;
    // Loop through each substring in the input string
    for (int i = 0; i < s.length(); i++) {
        // Initialize the substring as empty
        String sub = "";
        // Loop through each character in the substring
        for (int j = i; j < s.length(); j++) {
            // Check if the current substring is unique
            if (!sets.contains(sub)) {
                // If the substring is unique, add it to the set
                sets.add(sub);
                // Update the maximum number of unique substrings
                max = Math.max(max, sets.size());
            }
            // Add the current character to the substring
            sub += s.charAt(j);
        }
    }
    return max;
}

