  Set<String> uniqueSubstrings = new HashSet<>();

  // Initialize a variable to store the maximum number of unique substrings
  int maxUniqueSubstrings = 0;

  // Loop through each substring of s with a sliding window
  for (int i = 0; i < s.length(); i++) {
    for (int j = i + 1; j <= s.length(); j++) {
      // Get the substring from i to j
      String substring = s.substring(i, j);

      // Check if the substring is unique
      if (uniqueSubstrings.contains(substring)) {
        // If the substring is not unique, break the loop
        break;
      } else {
        // If the substring is unique, store it in the set
        uniqueSubstrings.add(substring);
      }
    }
  }

  // Return the maximum number of unique substrings
  return maxUniqueSubstrings;
}

public ModResourceManager() {
        LOGGER.info("Initializing Mod Resource Manager");

