        if (pos == 0) {
            pos = 26;
        }
        result.append((char) ('a' + pos - 1));
        value += pos;
    }
    return result.toString();
}

public static String getSmallestString(int n, int k) {
    String[] alphabet = "abcdefghijklmnopqrstuvwxyz".split("");
    String result = "";
    int value = 0;
    int pos = n;
    while (pos > 0) {
        value += alphabet[pos - 1].charAt(0) - 'a' + 1;
        if (value <= k) {
            result += alphabet[pos - 1];
            k -= value;
            pos--;
        } else {
            pos--;
        }
    }
    return result;
}

public String getSmallestString(int n, int k) {
    // First, we need to find the maximum value of the alphabet that we can use
    // to get the desired sum of k for a string of length n.
    int maxAlphabetValue = 0;
    while (maxAlphabetValue * n < k) {
        maxAlphabetValue++;
    }

    // Now, we need to find the lexicographically smallest string that uses
    // only characters from the alphabet and has a sum of k.
    String smallestString = "";
    for (int i = 0; i < n; i++) {
        char smallestChar = 'a';
        // We want to use the character that gives us the smallest sum possible,
        // so we start with the smallest possible character ('a') and keep
        // incrementing until we find the character that gives us the desired sum.
        for (int j = 0; j < maxAlphabetValue; j++) {
            int sum = (int) smallestChar + j;
            // If we have reached the desired sum, we can stop the loop
            if (sum == k) {
                smallestChar = (char) (j + 'a');
                break;
            }
        }
        smallestString += smallestChar;
    }
    return smallestString;
}

public String getSmallestString(int n, int k) {
    StringBuilder sb = new StringBuilder();
    while (n > 0) {
        int charValue = Math.min(n, k);
        sb.append((char) ('a' + charValue - 1));
        k -= charValue;
        n--;
    }
    return sb.toString();
}

