    // Calculate the number of ways the last passenger can sit in their own seat
    double lastSeatWays = 1;
    for (int i = 1; i <= n - 1; i++) {
        lastSeatWays *= (n - 1 - i + 1) / i;
    }
    // Calculate the total number of ways the passengers can sit
    double totalWays = 1;
    for (int i = 1; i <= n; i++) {
        totalWays *= i;
    }
    // Calculate the probability
    double probability = lastSeatWays / totalWays;
    return probability;
}

