    for (int i = 0; i < m; i++) {
        for (int j = 0; j + i < n; j++) {
            if (mat[i][j] == 1) {
                currentLength = 1;
                while (i + 1 < m && j + 1 < n && mat[i + 1][j + 1] == 1) {
                    currentLength++;
                    i++;
                    j++;
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }

    //anti-diagonal check
    for (int i = 0; i < m; i++) {
