    int[][] dp = new int[m][n];
    int max = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            /*
            Calculate the length of the longest continuous line of 1s
            starting from (i, j) by checking the neighbor cells.
            */
            int line = 0;
            if (mat[i][j] == 1) {
                line++;
                if (i > 0 && mat[i - 1][j] == 1) {
                    line = Math.max(line, dp[i - 1][j] + 1);
                }
                if (j > 0 && mat[i][j - 1] == 1) {
                    line = Math.max(line, dp[i][j - 1] + 1);
                }
                if (i < m - 1 && mat[i + 1][j] == 1) {
                    line = Math.max(line, dp[i + 1][j] + 1);
                }
                if (j < n - 1 && mat[i][j + 1] == 1) {
                    line = Math.max(line, dp[i][j + 1] + 1);
                }
            }
            dp[i][j] = line;
            max = Math.max(max, line);
        }
    }

    return max;
}

