public static boolean isBoomerang(int[][] points) {
    // Check if the input array has the correct length
    if (points.length != 3) {
        return false;
    }
    // Calculate the slope of the lines connecting the points
    double slope1 = (double)(points[1][1] - points[0][1]) / (double)(points[1][0] - points[0][0]);
    double slope2 = (double)(points[2][1] - points[1][1]) / (double)(points[2][0] - points[1][0]);
    // Check if the slopes are equal
    if (slope1 == slope2) {
        return false;
    }
    // Check if the points are aligned vertically or horizontally
    if (points[0][0] == points[1][0] && points[1][0] == points[2][0]) {
        return false;
    }
    if (points[0][1] == points[1][1] && points[1][1] == points[2][1]) {
        return false;
    }
    // Check if the points form a triangle
    if (Math.abs(slope1 * (points[2][0] - points[0][0])) > Math.abs(slope2 * (points[2][1] - points[0][1]))) {
        return false;
    }
    // Check if the points are on the same line
    if (Math.abs(slope1 * (points[2][0] - points[0][0])) == Math.abs(slope2 * (points[2][1] - points[0][1]))) {
        return false;
    }
    // If none of the above conditions are met, then the points form a boomerang
    return true;
}

