public static int minPerfectSquareSum(int n) {
    // Initialize a list to store the perfect square numbers
    List<Integer> perfectSquares = new ArrayList<>();

    // Iterate from 1 to the square root of n
    for (int i = 1; i * i <= n; i++) {
        // If i is a perfect square, add it to the list
        if (i * i == n) {
            perfectSquares.add(i);
        }
    }

    // Initialize a variable to store the minimum number of perfect squares
    int minSquares = Integer.MAX_VALUE;

    // Iterate over the powerset of the list of perfect squares
    for (List<Integer> combination : getSubsets(perfectSquares)) {
        // Calculate the sum of the current combination
        int sum = 0;
        for (int i : combination) {
            sum += i;
        }

        // If the sum is equal to n, update the minimum number of perfect squares
        if (sum == n) {
            minSquares = Math.min(minSquares, combination.size());
        }
    }

    return minSquares;
}

